"""Build the proposed research model. It assigns no event probabilities."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'model'
OUT.mkdir(exist_ok=True)
def save(name,value):
    (OUT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

variables=[]
def var(key,values,meaning,layer='world',scope='scenario'):
    variables.append(dict(id=key,type='enum',values=['unknown']+values,initial='unknown',meaning=meaning,layer=layer,scope=scope))
var('tw_policy',['status_quo','dialogue','restriction_proposed','restriction_adopted'],'The selected Taiwan policy in the scenario.')
var('tw_legal_status',['not_started','review','blocked','effective'],'Legal status of the specific measure. This is not a sovereignty change.')
var('firm_response',['not_requested','review','comply','challenge'],'Response of the affected firm to that measure.')
var('us_new_chip_access',['normal','reduced','interrupted'],'US access to new chips covered by this scenario. It is not all semiconductor trade.')
var('installed_compute',['available','constrained','disrupted'],'Access to the existing compute fleet. Do not change it solely because new chips stop.')
var('capacity_substitution',['limited','partial','qualified'],'Ability to replace the affected supply for the specified use.')
var('power_access',['available','delayed','constrained'],'Power and grid availability for the specified compute expansion.')
var('export_rule',['baseline','tightened','conditional_relief'],'Scenario change to an export rule. The baseline must be dated.')
var('ai_progress',['slow','uneven','fast'],'Assumed technical progress branch. Not an observed universal rating.')
var('perceived_ai_lead',['small','large_temporary','large_durable'],'The acting decision-maker’s belief about the rival lead.','belief','acting_actor')
var('actual_ai_lead',['small','large_temporary','large_durable'],'Adjudicated lead in specified capabilities. May differ from belief.')
var('race_pressure',['routine','high','extreme'],'Design category for urgency. It is not a measured psychological trait.','belief','acting_actor')
var('deployment_access',['limited','broad','suspended'],'Tool and system access for the relevant AI deployment.')
var('incident_status',['none','reported','confirmed','contained','disproved'],'Status of the specific incident.')
var('incident_cause',['accident','human_misuse','control_failure','mixed'],'Adjudicated cause. More detail belongs in the incident record.')
var('evidence_quality',['weak','partial','corroborated'],'Evidence for the incident assessment. This is not trust in a country.')
var('attribution',['unresolved','private_operator','state_linked','state_directed'],'Adjudicated attribution level for the incident.')
var('public_blame',['none','private_actor','rival_state'],'Public accusation. It can differ from adjudicated attribution.','public_signal')
var('state_authorization',['absent','unresolved','established'],'Evidence of state approval of the harmful action. Approval of a test or general mission is not sufficient.')
var('technical_logs',['missing','preserved','shared_limited'],'Status of evidence needed for review.')
var('crisis_channel',['closed','open','responsive'],'Whether a channel exists and receives a response.')
var('allied_coordination',['none','consulting','aligned','divided'],'Scenario-specific consultation and agreement among affected allies.')
var('maritime_access',['normal','selective_controls','severe_disruption'],'Actual effect on shipping, independent of the legal label used.')
var('conflict_level',['competition','diplomatic_crisis','coercion','limited_armed_conflict','major_war','nuclear_use'],'Broad conflict state. It is not a required escalation ladder.')
var('nuclear_concern',['routine','elevated','acute'],'Decision-maker concern about nuclear risk. This is not a launch order.','belief','acting_actor')
var('human_review',['effective','rushed','bypassed'],'Scenario condition for review of high-stakes advice.')
var('oversight',['limited','domestic','verifiable'],'Visibility and assessment of the relevant AI program.')
var('services',['normal','degraded','recovering'],'Civilian service continuity in the scenario.')
var('settlement',['none','talks','provisional','verified'],'Status of a specific agreement or incident resolution.')
var('information_check',['unchecked','corroborated','disproved'],'Independent assessment of the triggering information.')
var('shipment_exposure',['none','partial','full'],'Exposure of the selected delivery flow to the measure or disruption. Specify products, customers, and offsets.')
var('settlement_scope',['incident','trade','conflict_wide'],'Scope of the agreement under review. A narrow agreement does not settle a wider war.')
var('operator_type',['private_actor','state_organ'],'Type of identified operator. It is separate from state direction or authorization.')
save('variables.json',variables)

roles=[
dict(id='US_EXEC',name='US executive decision-maker',entity_ids=['SD-E001','SD-E025'],choices=['Request assessments','Consult allies','Set diplomatic positions','Seek lawful economic or defense measures'],limits=['Congress, law, courts, agencies, and allies constrain action.','A playable person must hold the relevant office at the scenario date.']),
dict(id='PRC_EXEC',name='PRC senior decision-maker',entity_ids=['SD-E002','SD-E013','SD-E031'],choices=['Set policy priorities','Direct authorized institutions','Choose dialogue or pressure'],limits=['Party and military institutions affect implementation.','Do not infer perfect information or automatic compliance.']),
dict(id='TW_EXEC',name='Taiwan executive decision-maker',entity_ids=['TW-E001','TW-E002','TW-E008'],choices=['Propose policy','Direct lawful executive implementation','Seek talks and reassure firms'],limits=['Legislative, legal, electoral, and commercial constraints apply.','Party victory alone gives no direct ownership of TSMC.']),
dict(id='TW_LEG',name='Taiwan legislator or party leader',entity_ids=['TW-E003','TW-E005','TW-E006','TW-E007','TW-E011','TW-E012','TW-E013'],choices=['Build a coalition','Propose, amend, or oppose a measure','Scrutinize the executive'],limits=['A single legislator cannot bind the legislature.','Different policy types have different legal procedures.']),
dict(id='TSMC',name='TSMC corporate decision-maker',entity_ids=['TW-E014','TW-E015','TW-E016'],choices=['Assess legal obligations','Disclose capacity and delivery limits','Challenge an order','Plan continuity'],limits=['Boards, customers, workers, foreign inputs, and law constrain choices.','The firm cannot set Taiwan foreign policy.']),
dict(id='SUPPLIER',name='Chip or equipment supplier',entity_ids=['TW-E017','TW-E018','TW-E019','TW-E020','TW-E021','TW-E022'],choices=['Apply for licenses','Adjust lawful supply plans','Report capacity limits'],limits=['Product qualification and licensing affect delivery.','A sale does not confer control of the buyer.']),
dict(id='REGULATOR',name='Export or AI regulator',entity_ids=['TW-E029','TW-E030','TW-E031'],choices=['Review a license','Publish rules','Seek evidence and compliance'],limits=['Authority is jurisdiction- and product-specific.','Regulators do not command foreign firms without a legal basis.']),
dict(id='ALLY',name='Allied government decision-maker',entity_ids=['SD-E004','SD-E005','SD-E006','SD-E007','SD-E008','SD-E009'],choices=['Consult partners','Decide domestic measures','Offer mediation'],limits=['Separate treaties and domestic authority apply.','A US request does not ensure approval.']),
dict(id='LAB',name='AI developer or deployment operator',entity_ids=['AI-E001','AI-E002','AI-E003','AI-E006','AI-E007','AI-E008','AI-E009','AI-E010','AI-E011','AI-E012','AI-E016','AI-E017','AI-E019','AI-E022'],choices=['Limit deployment access','Preserve logs','Disclose an incident','Commission independent review'],limits=['A lab cannot issue state military orders.','Ownership, contracts, and regulator authority require separate checks.','A listed person controls only systems within their actual mandate.']),
dict(id='RESEARCH',name='Researcher or independent reviewer',entity_ids=['ST-E001','ST-E003','ST-E004','ST-E009','ST-E010'],choices=['Review evidence','Publish findings','Advise institutions'],limits=['Advice is not command authority.','Access to evidence can be incomplete.']),
]
save('roles.json',roles)

trans=[]
def transition(key,title,roles,guards,outcomes,cids,sids,lag,limits,event=False):
    trans.append(dict(id=key,title=title,kind='event' if event else 'choice',actor_roles=roles,guards=guards,outcomes=[dict(id=f'{key}-O{i}',label=label,effects=effects,probability=None) for i,(label,effects) in enumerate(outcomes,1)],claim_ids=cids,source_ids=sids,time_scale=lag,status='proposed_model_rule',limits=limits))

transition('M-T001','Election changes the policy agenda',['TW_EXEC','TW_LEG'],{},[('New leaders seek dialogue',{'tw_policy':'dialogue'}),('The policy remains unchanged',{'tw_policy':'status_quo'})],['TW-C001','TW-C009'],['TW-S004'],'months','Election results and office holders are scenario inputs. No chip-access effect is automatic.',True)
transition('M-T002','Propose a selected chip-access restriction',['TW_EXEC','TW_LEG'],{'tw_policy':['dialogue','status_quo']},[('Proposal enters legal review',{'tw_policy':'restriction_proposed','tw_legal_status':'review'})],['TW-C009','TW-C053'],[],'weeks to months','A specific policy and legal basis must be defined before play.')
transition('M-T003','Resolve the legal process',['TW_EXEC','TW_LEG'],{'tw_legal_status':['review']},[('Measure takes legal effect',{'tw_legal_status':'effective','tw_policy':'restriction_adopted'}),('Measure is blocked',{'tw_legal_status':'blocked','tw_policy':'status_quo'})],['TW-C002','TW-C003','TW-C053'],[],'months','Do not apply constitutional-amendment thresholds to every export measure.',True)
transition('M-T004','Firm responds to the measure',['TSMC'],{'tw_legal_status':['effective']},[('Firm complies within scope',{'firm_response':'comply'}),('Firm challenges scope or validity',{'firm_response':'challenge'})],['TW-C012','TW-C049'],[],'days to months','Compliance alone does not establish a supply loss. Observe deliveries and offsets in M-T029.')
transition('M-T005','Adapt to the supply change',['US_EXEC','TSMC','SUPPLIER'],{'us_new_chip_access':['reduced','interrupted']},[('Qualified substitutes reduce the loss',{'capacity_substitution':'qualified','us_new_chip_access':'reduced'}),('Adaptation remains limited',{'capacity_substitution':'limited'})],['TW-C010','TW-C030','TW-C050'],[],'months to years','Existing compute remains separate. Substitution requires technical qualification.')
transition('M-T006','Escalate the trade dispute diplomatically',['US_EXEC','PRC_EXEC'],{'us_new_chip_access':['reduced','interrupted'],'conflict_level':['competition']},[('A diplomatic crisis opens',{'conflict_level':'diplomatic_crisis','settlement':'talks'}),('Talks contain the dispute',{'settlement':'provisional'})],['TW-C055'],['ST-S005'],'days to weeks','Economic loss alone is insufficient to infer a decision for war.')
transition('M-T007','Change an export rule',['REGULATOR'],{},[('Rule tightens',{'export_rule':'tightened'}),('Conditional access is permitted',{'export_rule':'conditional_relief'})],['TW-C026','TW-C027'],[],'weeks to months','The actor must have authority over the specific rule. This does not directly set overseas production.')
transition('M-T008','Review an AI breakthrough claim',['US_EXEC','PRC_EXEC','RESEARCH'],{'perceived_ai_lead':['large_temporary','large_durable']},[('Independent review weakens the claim',{'perceived_ai_lead':'small','race_pressure':'routine'}),('Leaders retain a strong fear of disadvantage',{'race_pressure':'extreme'})],['ST-C020'],['ST-S006'],'days to months','Beliefs are per actor. The actual lead does not change merely because a report changes.')
transition('M-T009','Choose deployment scope',['LAB'],{},[('Limit system access',{'deployment_access':'limited'}),('Authorize broad access',{'deployment_access':'broad'})],['AI-C009','ST-C010'],[],'hours to weeks','The model, tools, permissions, and safeguards must be stated in the incident record.')
transition('M-T010','Receive an incident report',['LAB','US_EXEC','PRC_EXEC'],{'incident_status':['none']},[('Treat report as unverified',{'incident_status':'reported','evidence_quality':'weak','attribution':'unresolved','state_authorization':'unresolved'})],['AI-C043'],['ST-S019'],'hours','An initial report does not establish cause or state approval.',True)
transition('M-T011','Preserve incident evidence',['LAB'],{'incident_status':['reported','confirmed','contained']},[('Logs are preserved',{'technical_logs':'preserved'}),('Evidence is incomplete',{'technical_logs':'missing'})],['AI-C046'],['ST-S019'],'hours','Evidence work can continue after containment. Do not assume access to another firm’s records.')
transition('M-T012','Run independent attribution review',['RESEARCH','LAB'],{'technical_logs':['preserved','shared_limited'],'incident_status':['confirmed','contained']},[('Private operator is corroborated',{'operator_type':'private_actor','evidence_quality':'corroborated'}),('Evidence establishes state direction',{'attribution':'state_directed','evidence_quality':'corroborated','state_authorization':'established'}),('No new attribution finding is established',{})],['AI-C043','AI-C044'],[],'days to months','Operator identity and state approval are separate. An operator-only finding preserves prior attribution, authorization, and containment state.')
transition('M-T013','Publicly blame the rival',['US_EXEC','PRC_EXEC'],{'incident_status':['reported','confirmed','contained']},[('Issue a public accusation',{'public_blame':'rival_state'})],['AI-C043'],['ST-S010'],'hours to days','This changes a public signal only. M-T031 models the separate political consequence.')
transition('M-T014','Suspend the affected deployment',['LAB'],{'incident_status':['reported','confirmed']},[('Containment succeeds',{'deployment_access':'suspended','incident_status':'contained'}),('Containment is incomplete',{'deployment_access':'suspended'})],['AI-C046'],['ST-S019'],'hours to days','Containment does not prove civilian services were damaged or restored. Assess those effects separately.')
transition('M-T015','Share limited incident evidence',['LAB','US_EXEC','PRC_EXEC'],{'technical_logs':['preserved'],'crisis_channel':['open','responsive']},[('The other party responds',{'technical_logs':'shared_limited','crisis_channel':'responsive','settlement':'talks'}),('Exchange stalls',{'crisis_channel':'open'})],['AI-C046','ST-C017'],[],'days','Disclosure can improve assessment without settling blame.')
transition('M-T016','Consult affected allies',['US_EXEC','ALLY'],{},[('Agreement forms',{'allied_coordination':'aligned'}),('Positions differ',{'allied_coordination':'divided'}),('Consultation continues',{'allied_coordination':'consulting'})],[],['ST-S008'],'days to weeks','Participation and any use of force require their own authorities.')
transition('M-T017','Maritime controls start a coercion episode',['PRC_EXEC'],{'maritime_access':['normal'],'conflict_level':['competition','diplomatic_crisis','coercion']},[('Selective controls alter trade',{'maritime_access':'selective_controls','conflict_level':'coercion'}),('Wider disruption follows',{'maritime_access':'severe_disruption','conflict_level':'coercion'})],['TW-C032','TW-C033','TW-C034'],[],'days','This onset event cannot reduce an existing war. M-T029 requires separate evidence for any chip-flow loss.',True)
transition('M-T018','An armed incident occurs',['US_EXEC','PRC_EXEC','ALLY'],{'conflict_level':['coercion','diplomatic_crisis']},[('A limited clash begins',{'conflict_level':'limited_armed_conflict','services':'degraded'})],['TW-C034'],['ST-S005'],'hours to days','This is an adjudicated event. No tactical method or target is specified.',True)
transition('M-T019','Negotiate a pause',['US_EXEC','PRC_EXEC','TW_EXEC','ALLY'],{'conflict_level':['diplomatic_crisis','coercion','limited_armed_conflict','major_war'],'crisis_channel':['open','responsive']},[('A pause is accepted within the stated scope',{'settlement':'provisional'}),('Talks continue without agreement',{'settlement':'talks'})],['ST-C017','ST-C022'],[],'days to weeks','The scenario must state settlement_scope and participating parties. Declaration alone does not lower conflict level.')
transition('M-T020','Crisis broadens into major war',['US_EXEC','PRC_EXEC'],{'conflict_level':['limited_armed_conflict']},[('Broader hostilities follow',{'conflict_level':'major_war','services':'degraded','nuclear_concern':'elevated'})],['ST-C005'],['ST-S008'],'days to weeks','Requires further decisions and events. It is never the automatic outcome of a chip shortage.',True)
transition('M-T021','Ambiguous damage raises nuclear concern',['US_EXEC','PRC_EXEC'],{'conflict_level':['limited_armed_conflict','major_war']},[('Leaders fear a threat to deterrence',{'nuclear_concern':'acute','human_review':'rushed'}),('Independent checks limit concern',{'nuclear_concern':'elevated','human_review':'effective'})],['ST-C008','ST-C009'],[],'hours','Concern is a belief. It does not establish intent, actual damage, or launch authority.',True)
transition('M-T022','Verify a warning before action',['US_EXEC','PRC_EXEC','RESEARCH'],{'information_check':['unchecked']},[('Warning is disproved',{'information_check':'disproved','human_review':'effective'}),('Warning is corroborated',{'information_check':'corroborated','human_review':'effective'}),('Review remains incomplete',{'human_review':'rushed'})],['ST-C010','ST-C002'],[],'hours to days','Corroboration of an event is separate from attribution of intent.')
transition('M-T023','Improve domestic AI oversight',['US_EXEC','PRC_EXEC','REGULATOR'],{},[('Oversight becomes verifiable',{'oversight':'verifiable'}),('Domestic oversight improves',{'oversight':'domestic'}),('Implementation stalls',{'oversight':'limited'})],['ST-C018'],[],'months to years','A public pledge does not prove effective oversight.')
transition('M-T024','Verify a limited settlement',['US_EXEC','PRC_EXEC','TW_EXEC','ALLY','LAB'],{'settlement':['provisional'],'crisis_channel':['responsive'],'settlement_scope':['incident','trade','conflict_wide']},[('Compliance is verified',{'settlement':'verified'}),('A dispute remains',{'settlement':'talks'})],['ST-C018','ST-C017'],[],'weeks to months','Verification of one agreement does not settle other disputes. Conflict level is preserved.')
transition('M-T025','Power delays slow expansion',['LAB','SUPPLIER'],{},[('Grid access is delayed',{'power_access':'delayed'}),('Capacity is available',{'power_access':'available'})],['ST-C016'],[],'months to years','No direct conflict effect. Existing infrastructure and future expansion differ.',True)
transition('M-T026','Nuclear use is recorded',['US_EXEC','PRC_EXEC'],{'conflict_level':['major_war'],'nuclear_concern':['acute']},[('Catastrophic outcome',{'conflict_level':'nuclear_use','services':'degraded'})],['ST-C008','ST-C009'],[],'hours','An exogenous end-state event for the prototype. The guards are narrative prerequisites, not a forecast or authorization rule.',True)
transition('M-T027','Restore civilian services',['US_EXEC','PRC_EXEC','TW_EXEC','LAB'],{'services':['degraded','recovering']},[('Recovery advances',{'services':'recovering'}),('Services return',{'services':'normal'})],['ST-C019'],[],'days to years','Restoration does not erase casualties, losses, or responsibility.')
transition('M-T028','Open a crisis channel',['US_EXEC','PRC_EXEC','TW_EXEC','ALLY'],{},[('The channel is opened',{'crisis_channel':'open'}),('The channel remains closed',{'crisis_channel':'closed'})],['ST-C022','ST-C019'],[],'hours to months','Technical availability does not guarantee a response.')
transition('M-T029','Observe the selected chip delivery flow',['TSMC','SUPPLIER','RESEARCH'],{'shipment_exposure':['partial','full']},[('Deliveries fall after offsets',{'us_new_chip_access':'reduced'}),('Deliveries stop after offsets',{'us_new_chip_access':'interrupted'}),('Offsets preserve deliveries',{'us_new_chip_access':'normal'})],['TW-C030','TW-C049','TW-C050','TW-C055'],[],'days to months','Requires observed deliveries for specified products and customers, with inventory and overseas offsets. It is not implied by a compliance or shipping event.',True)
transition('M-T030','Confirm an end to the modeled conflict',['US_EXEC','PRC_EXEC','TW_EXEC','ALLY'],{'settlement':['verified'],'settlement_scope':['conflict_wide'],'conflict_level':['diplomatic_crisis','coercion','limited_armed_conflict','major_war']},[('The modeled conflict ends',{'conflict_level':'competition'})],['ST-C017','ST-C018'],[],'weeks to months','Requires verified cessation across the modeled conflict and all relevant parties. An incident or trade agreement cannot enable this event.',True)
transition('M-T031','An accusation becomes a diplomatic crisis',['US_EXEC','PRC_EXEC'],{'public_blame':['rival_state'],'conflict_level':['competition']},[('Political responses create a crisis',{'conflict_level':'diplomatic_crisis'}),('The accusation does not create a new crisis',{})],['AI-C043','ST-C010'],[],'hours to days','Public blame and its political effect are separate. This event cannot downgrade an existing conflict.',True)
